def _start_client_span(
    client: "sentry_sdk.client.BaseClient",
    service_id: "ServiceId",
    operation_name: str,
) -> "Union[Span, StreamedSpan, None]":
    description = "aws.%s.%s" % (service_id.hyphenize(), operation_name)

    if has_span_streaming_enabled(client.options):
        if sentry_sdk.traces.get_current_span() is None:
            return None

        # The span is made current manually for the duration of the call only, since it
        # may outlive the call while a `StreamingBody` is open.
        return sentry_sdk.traces.start_span(
            name=description,
            active=False,
            attributes={
                "sentry.op": OP.HTTP_CLIENT,
                "sentry.origin": ORIGIN,
                SPANDATA.RPC_METHOD: f"{service_id}/{operation_name}",
            },
        )

    span = sentry_sdk.start_span(
        op=OP.HTTP_CLIENT,
        name=description,
        origin=ORIGIN,
    )
    span.set_tag("aws.service_id", service_id.hyphenize())
    span.set_tag("aws.operation_name", operation_name)
    return span


