        yield
        return

    scope = sentry_sdk.get_current_scope()
    if isinstance(span, StreamedSpan):
        old_streamed_span = scope.streamed_span
        scope.streamed_span = span
        try:
            yield
        finally:
            scope.streamed_span = old_streamed_span
